/** Returns the flat annual subscription price in dollars for a given tier. */
export function getAnnualPrice(tierId: TierId): number | null {
  const tier = TIERS.find((t) => t.id === tierId);
  return tier ? tier.baseAnnual : null;
}

/** Returns the total annual charge in dollars for a tier and rentable unit count. */
export function getAnnualTotal(tierId: TierId, unitCount: number): number | null {
  const tier = TIERS.find((t) => t.id === tierId);
  if (!tier || tier.baseAnnual == null) return null;
  const resolvedUnitCount = Math.max(Math.floor(unitCount), tier.minUnits);
  if (tier.unitPricingBands?.length) {
    return tier.baseAnnual + tier.unitPricingBands.reduce((total, band) => {
      if (resolvedUnitCount < band.minUnits) return total;
      const bandMax = band.maxUnits ?? resolvedUnitCount;
      const bandUnitCount = Math.max(
        Math.min(resolvedUnitCount, bandMax) - band.minUnits + 1,
        0,
      );
      return total + bandUnitCount * band.pricePerUnitAnnual;
    }, 0);
  }
  if (tier.pricePerUnitAnnual == null) return null;
  const overageUnits = Math.max(resolvedUnitCount - tier.includedUnits, 0);
  return tier.baseAnnual + overageUnits * tier.pricePerUnitAnnual;
}

/** Returns the first-year launch offer price in dollars for a tier. */
export function getLaunchOfferAnnualPrice(tierId: TierId, unitCount = 1): number | null {
  const annualTotal = getAnnualTotal(tierId, unitCount);
  if (annualTotal == null) return null;
  return Math.ceil(annualTotal * (1 - LAUNCH_OFFER.discountPercent / 100));
}

/** Returns the tier id that applies to a given rentable unit count. */
export function getBandForCount(count: number): TierId {
  for (const tier of TIERS) {
    if (tier.maxUnits == null) return tier.id;
    if (count <= tier.maxUnits) return tier.id;
  }
  const last = TIERS[TIERS.length - 1];
  if (!last) throw new Error("TIERS is empty");
  return last.id;
}

/** Returns feature keys available for a given tier (includes all lower tiers). */
export function getFeaturesForTier(tierId: TierId): FeatureKey[] {
  const tierIndex = TIERS.findIndex((t) => t.id === tierId);
  if (tierIndex === -1) return [];
  const includedTierIds = new Set(TIERS.slice(0, tierIndex + 1).map((t) => t.id));
  return FEATURES.filter((f) => includedTierIds.has(f.tier)).map((f) => f.key);
}

/** Check if a specific feature is available in a given tier. */
export function hasFeature(tierId: TierId, featureKey: FeatureKey): boolean {
  return getFeaturesForTier(tierId).includes(featureKey);
}
